SELECT s.superhero_name AS commercial_title, p.publisher_name AS media_production_company
FROM superhero AS s
JOIN publisher AS p ON s.publisher_id = p.id;

SELECT name FROM (
    SELECT superhero_name AS name FROM superhero
    UNION
    SELECT full_name AS name FROM superhero WHERE full_name IS NOT NULL AND full_name <> ''
) ORDER BY name;

SELECT superhero_name
FROM superhero
WHERE superhero_name LIKE 'A%';

